    /// File ▸ Pause Recording / Resume Recording (the header). A tool's
    /// status item flips at once, on the recorder's
    /// `pauseDidChangeNotification` (#181).
    @objc func pauseOrResumeRecording(_ sender: Any?) {
        let panel = RecorderPanelController.shared
        switch panel.phase {
        case .recording:
            panel.pauseRecording()
        case .paused:
            panel.resumeRecording()
        default:
            let recorder = ScreenRecorder.shared
            do {
                if recorder.isPaused { try recorder.resume() } else { try recorder.pause() }
            } catch {
                NSSound.beep()
            }
        }
    }

    /// The welcome window's New Recording… button (the header): the panel
    /// shown, or a beep while a recording has it hidden.
    @objc func showRecorderPanel(_ sender: Any?) {
        RecorderPanelController.shared.show()
    }

